{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "The agent combines model-based and model-free Q-values for stage 1 using a weighting parameter.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A bonus is added to the stage 1 Q-value of the action chosen in the previous trial.",
      "params": [
        {
          "name": "rho",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\nif last_action != -1:\n    stickiness[last_action] = rho\nq1_vals = beta_1 * q_stage1_net + stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "learned_transition_matrix",
      "title": "Learned Transition Matrix",
      "description": "The agent dynamically updates its belief about the transition probabilities from experience using a learning rate.",
      "params": [
        {
          "name": "alpha_t",
          "bounds": [0, 1]
        }
      ],
      "evidence": "transition_matrix[action_1[trial], state_idx] += alpha_t * (1 - transition_matrix[action_1[trial], state_idx])\ntransition_matrix[action_1[trial], 1 - state_idx] += alpha_t * (0 - transition_matrix[action_1[trial], 1 - state_idx])",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage 1 model-free Q-values are updated using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "The Q-values of all unchosen actions in both stages decay towards zero at a constant rate.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_a1 = 1 - action_1[trial]\nq_stage1_mf[unchosen_a1] *= (1 - decay)\nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] *= (1 - decay)",
      "expressible_in_slots": true
    }
  ]
}
